def render():
    # 运营在后台填写通知模板，用沙箱渲染
    return env.from_string(request.args["tpl"]).render(user="test")



### app.py:12

@app.get("/render")
def render():
    # 运营在后台填写通知模板，用沙箱渲染
    return env.from_string(request.args["tpl"]).render(user="test")


@app.get("/weather")
def weather():
